"""Invitation landing page: no fetch, analytics, reservation or token in the HTTP URL."""
import base64
import hashlib
_SCRIPT="""const fragment=location.hash.slice(1);const valid=/^[A-Za-z0-9_-]{43}$/.test(fragment);const open=document.getElementById('open');if(valid){open.href='veil-contact://open?link='+encodeURIComponent(location.origin+'/i#'+fragment);open.hidden=false;}else{document.getElementById('status').textContent='This invitation is incomplete. Ask your contact to share it again.';}"""
CSP="default-src 'none'; script-src 'sha256-"+base64.b64encode(hashlib.sha256(_SCRIPT.encode()).digest()).decode()+"'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'"
HTML=('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Veil invitation</title><style>body{font:18px system-ui;background:#0b1014;color:#eef6f0;max-width:32em;margin:12vh auto;padding:24px;line-height:1.6}a{display:inline-block;color:#b5f4cf;padding:12px 0;min-height:24px}h1{font-size:36px;line-height:1.2}</style><h1>A private invitation.</h1><p id="status">Preview the contact rules in Veil. Opening this page does not send a request.</p><a id="open" hidden>Open in Veil</a><p>Install the Veil contact preview first, then tap this invitation again. If Android asks, allow Veil to open supported links. You can also copy the complete link from your conversation and use “Open an invitation” in Veil.</p><p>Only request contact if you trust the person who sent the link. Approval is required.</p><script>'''+_SCRIPT+'''</script></html>''').encode()
